+        """;
+    assertThat(checkSyntax(program))
+        .containsExactly(
+            new IncludeStatement("hullo", Location.fromFileLineColumn("test file", 2, 1)),
+            new IncludeStatement("world", Location.fromFileLineColumn("test file", 4, 1)));
+  }
